def consolidate_roles_forward(apps, schema_editor):
    User = apps.get_model('accounts', 'User')
    RoleMigrationAudit = apps.get_model('accounts', 'RoleMigrationAudit')
    ExtractedFact = apps.get_model('facts', 'ExtractedFact')
    Document = apps.get_model('documents', 'Document')
    EvidenceRequest = apps.get_model('facts', 'EvidenceRequest')
    Recommendation = apps.get_model('recommendations', 'Recommendation')

    LEGACY_COLLEGE_ROLES = {
        'institution_admin', 'registrar', 'hod', 'hr_officer',
        'lab_admin', 'placement_officer', 'faculty', 'iqac_coordinator',
    }

    users_converted_count = 0
    viewers_deactivated_count = 0

    for user in User.objects.all():
        original_role = user.role
        original_active = user.is_active

        if original_role == 'viewer':
            # Do NOT silently give former read-only viewers write access.
            # Safely deactivate their account, preserve identity, record original role.
            user.is_active = False
            notes = 'Deactivated former read-only viewer account during 3-role consolidation'
            dept = user.department_name or ''
            if 'former viewer' not in dept.lower():
                user.department_name = (f'{dept} [Deactivated former viewer]').strip()
            user.save(update_fields=['is_active', 'department_name'])
            viewers_deactivated_count += 1

            RoleMigrationAudit.objects.create(
                user_id=user.id,
                email=user.email,
                username=user.username,
                original_role=original_role,
                new_role=user.role,
                original_is_active=original_active,
                new_is_active=False,
                notes=notes,
            )

        elif original_role in LEGACY_COLLEGE_ROLES:
            if original_role != 'iqac_coordinator':
                user.role = 'iqac_coordinator'
                user.save(update_fields=['role'])
                users_converted_count += 1

            RoleMigrationAudit.objects.create(
                user_id=user.id,
                email=user.email,
                username=user.username,
                original_role=original_role,
                new_role='iqac_coordinator',
                original_is_active=original_active,
                new_is_active=user.is_active,
                notes=f'Converted legacy college role {original_role} to iqac_coordinator',
            )

    # 2. ExtractedFact owner_role conversion
    legacy_fact_roles = [
        'institution_admin', 'registrar', 'hod', 'hr_officer',
        'lab_admin', 'placement_officer', 'faculty',
    ]
    facts_updated_count = ExtractedFact.objects.filter(owner_role__in=legacy_fact_roles).update(owner_role='iqac_coordinator')

    # 3. Document owner_role conversion (both upper and lowercase variants)
    legacy_doc_roles = [
        'HOD', 'REGISTRAR', 'PLACEMENT_OFFICER', 'HR_OFFICER', 'LAB_ADMIN', 'INSTITUTION_ADMIN', 'FACULTY',
        'hod', 'registrar', 'placement_officer', 'hr_officer', 'lab_admin', 'institution_admin', 'faculty',
    ]
    docs_updated_count = Document.objects.filter(owner_role__in=legacy_doc_roles).update(owner_role='IQAC_COORDINATOR')

    # 4. EvidenceRequest suggested_owner_role conversion
    requests_updated_count = EvidenceRequest.objects.filter(suggested_owner_role__in=legacy_fact_roles).update(suggested_owner_role='iqac_coordinator')

    # 5. Recommendation owner_role conversion
    recs_updated_count = Recommendation.objects.filter(owner_role__in=legacy_fact_roles).update(owner_role='iqac_coordinator')

    # Verification: Ensure no active account remains with a removed legacy role
    active_legacy_users = User.objects.filter(
        is_active=True,
    ).exclude(role__in=['super_admin', 'consultant', 'iqac_coordinator'])

    if active_legacy_users.exists():
        emails = list(active_legacy_users.values_list('email', flat=True))
        raise RuntimeError(f'Migration failed: active accounts found with legacy roles: {emails}')

    print(
        f'\n--- ROLE CONSOLIDATION MIGRATION REPORT ---\n'
        f'Active college users converted to iqac_coordinator: {users_converted_count}\n'
        f'Viewer accounts safely deactivated & audited: {viewers_deactivated_count}\n'
        f'Extracted facts migrated to iqac_coordinator: {facts_updated_count}\n'
        f'Documents migrated to IQAC_COORDINATOR: {docs_updated_count}\n'
        f'Evidence requests migrated: {requests_updated_count}\n'
        f'Recommendations migrated: {recs_updated_count}\n'
        f'Active accounts with removed legacy roles: 0\n'
        f'-------------------------------------------\n'
    )


def consolidate_roles_reverse(apps, schema_editor):
    User = apps.get_model('accounts', 'User')
    RoleMigrationAudit = apps.get_model('accounts', 'RoleMigrationAudit')

    for record in RoleMigrationAudit.objects.all():
        User.objects.filter(id=record.user_id).update(
            role=record.original_role,
            is_active=record.original_is_active,
        )


